export type ConfigurationLocale = 'en' | 'de' | 'fr' | 'es';

type Localized = Record<ConfigurationLocale, string>;
export type ValueLine = { label?: 'default' | 'options'; text?: string; translationKey?: string };
export type ConfigurationRow = {
  name: string;
  type: string;
  typeTranslationKey?: string;
  qualifier?: 'pro' | 'required' | 'requiredDates' | 'requiredRichData';
  values?: ValueLine[];
  detail: Localized;
};
export type ConfigurationGroup = { id: string; intro?: Localized; rows: ConfigurationRow[] };

const l = (en: string, de: string, fr: string, es: string): Localized => ({ en, de, fr, es });
const bool = [{ label: 'default' as const, text: 'False' }];
const example = (locale: ConfigurationLocale, page: 'examples' | 'advanced-use', anchor: string) => `${locale === 'en' ? '' : `/${locale}`}/${page}#${anchor}`;

export const intro = l(
  'The following list holds all potential attributes to set up and customize your next Add to Calendar Button.\n\n*Check the Demo to play with most of them and explore the examples pages for more extensive descriptions for specific cases.*\n\nTo specify a boolean value within the HTML custom element, you would only add the name as attribute.\nNot setting it would automatically reflect to "false". As an alternative, you could also always write it as a string like `attributeName="true"`.',
  'Die nachfolgende Liste beinhaltet alle möglichen Attribute, um deinen Add to Calendar Button nach deinen Wünschen zu konfigurieren.\n\n*Wirf unbedingt auch einen Blick auf unsere Demo, bei welcher du mit den meisten Paramtern live herumspielen kannst - und durchstöbere die "Beispiele"-Seiten für weitere Erläuterungen und speziellere Funktionalitäten.*\n\nUm einen boolschen Wert in dem HTML-Element zu definieren, kannst du einfach nur den Namen als Attribute setzen.\nWenn er nicht gesetzt ist, definiert das die Option automatisch als "false". Alternativ kannst du den Wert aber auch immer vollständig als String ergänzen: `attributeName="true"`.',
  'La liste suivante contient tous les attributs possibles pour configurer et personnaliser votre prochain bouton Add to Calendar.\n\n*Consultez la démo pour essayer la plupart d’entre eux et parcourez les pages d’exemples pour obtenir des descriptions plus détaillées de cas particuliers.*\n\nPour définir une valeur booléenne dans l’élément HTML personnalisé, il suffit d’ajouter le nom de l’attribut.\nS’il n’est pas défini, sa valeur est automatiquement « false ». Vous pouvez également toujours l’écrire sous forme de chaîne, par exemple `attributeName="true"`.',
  'La siguiente lista contiene todos los atributos posibles para configurar y personalizar tu próximo botón Add to Calendar.\n\n*Consulta la demo para probar la mayoría de ellos y explora las páginas de ejemplos para obtener descripciones más amplias de casos específicos.*\n\nPara especificar un valor booleano en el elemento HTML personalizado, basta con añadir el nombre como atributo.\nSi no se establece, su valor será automáticamente «false». Como alternativa, también puedes escribirlo siempre como cadena, por ejemplo `attributeName="true"`.',
);

